"""Generate Pennsylvania from the shared guide UI and separate state records."""
import copy
import json
import re

BASE = 'https://travisvought-byte.github.io/vhg-veteran-resident-guide/'

def replace_line(html, prefix, new):
    html, n = re.subn(r'^' + re.escape(prefix) + r'.*$', lambda _: new, html, count=1, flags=re.M)
    if n != 1:
        raise ValueError('Missing template section: ' + prefix)
    return html

def pennsylvania_resources(root, ohio):
    ids = json.loads((root / 'data/public/federal-resource-ids.json').read_text())
    by_id = {r['program_id']: r for r in ohio}
    shared = []
    for id in ids:
        r = copy.deepcopy(by_id[id])
        r['service_area'] = ['National']
        r['state'] = 'shared'
        shared.append(r)
    return shared + json.loads((root / 'data/public/pa-programs.json').read_text())

def make_pa(html, resources, counties):
    # Remove Ohio payloads before adapting text: state data must never be relabeled.
    html = replace_line(html, 'const DATA=', 'const DATA=[];')
    html = replace_line(html, 'const COUNTIES=', 'const COUNTIES=[];')
    html = html.replace('Ohio', 'Pennsylvania').replace('All 88', 'All 67').replace('all 88', 'all 67')
    html = html.replace('<option value="OH">Pennsylvania</option>', '<option value="OH">Ohio</option>')
    html = html.replace('Choose an Pennsylvania county', 'Choose a Pennsylvania county')
    html = html.replace("'ohio'", "'pennsylvania'").replace("const STATE='OH';", "const STATE='PA';")
    html = html.replace('href="' + BASE + '"', 'href="' + BASE + 'pa.html"').replace('property="og:url" content="' + BASE + '"', 'property="og:url" content="' + BASE + 'pa.html"')
    html = html.replace('assets/share-preview.png', 'assets/vhg-logo.png').replace('content="1200"', 'content="715"').replace('content="630"', 'content="715"')
    html = html.replace('href="share.html"', 'href="share-pa.html"')
    html = html.replace('href="prototype-data.json"', 'href="data/public/pennsylvania-resources.json"').replace('href="data/public/ohio-county-veterans-offices.json"', 'href="data/public/pennsylvania-county-veterans-offices.json"')
    html = html.replace('Phone published in the 2025–2026 AMVETS directory', 'Phone published in the September 2026 PA DMVA directory').replace('AMVETS directory source', 'PA DMVA directory source')
    html = re.sub(r'<div class="coverage notice">.*?</div>', '<div class="coverage notice"><strong>Pennsylvania coverage:</strong> Veterans office contacts for all 67 counties, plus statewide programs and federal referrals. Aging and ombudsman help uses official statewide routing and lookup links; individual local agencies are not yet mapped here. County contacts are directory-published, not telephone-confirmed. Local grants, posts and contractors are still being researched.</div>', html, count=1)
    html = html.replace('Most phones come from Pennsylvania AMVETS’ 2025–2026 directory.', 'Phones come from PA DMVA’s September 9, 2026 county directory.')
    html = html.replace('Statewide edition · Updated', 'Pennsylvania edition · Updated')
    html = html.replace('Pennsylvania’s waiver rule specifies proposal and approval requirements; VA and other funders have their own processes.', 'Ask your Pennsylvania service coordinator or funding agency about proposal, owner-consent and provider requirements; VA and other funders have their own processes.')
    html = html.replace('https://codes.ohio.gov/ohio-administrative-code/rule-5160-44-13', 'https://www.pa.gov/agencies/dhs/resources/home-community-based-services-hcbs').replace('Pennsylvania home modification authorization and provider rules', 'Pennsylvania home and community-based services')
    html = replace_line(html, 'const priority=', "const priority=['pa-link','pa-aging-directory','pa-options','pa-chc','pa-ombudsman','r02-aid-attendance-housebound','r02-va-pension','r02-survivors-pension','r02-dic','r02-va-health-enrollment','pa-medi','pa-nht','pa-techowl-reuse','va-accredited-help'];")
    html = replace_line(html, 'const routes=', "const routes={benefits:['r02-aid-attendance-housebound','r02-va-pension','r02-disability-increase','r02-pension-medicaid-rule','r02-survivors-pension','r02-dic','pa-chc','pa-hcbs','pa-medi','va-accredited-help'],survivors:['r02-survivors-pension','r02-dic','r02-aid-attendance-housebound','r02-va-burial','va-accredited-help','nara-discharge-records'],care:['r02-va-health-enrollment','va-location-finder','r02-va-cnh','r02-va-clc','r02-general-caregiver','r02-family-caregiver','r02-hospice','r02-palliative','pa-caregiver-support','pa-nht'],rights:['pa-ombudsman','pa-disability-rights','pa-link'],local:['pa-link','pa-aging-directory','pa-options','pa-caregiver-support','pa-chc','pa-hcbs','pa-nht','pa-techowl-reuse','pa-techowl-library','pa-patf'],housing:['va-housing-help','nara-discharge-records','va-location-finder','va-accredited-help','pa-phfa-access','usda-pa-home-repair']};")
    html = replace_line(html, 'routes.accessibility=', "routes.accessibility=['va-hisa','va-sah','va-sha','va-tra','pa-chc','pa-hcbs','pa-options','pa-caregiver-support','pa-techowl-reuse','pa-techowl-library','pa-patf','pa-phfa-access','usda-pa-home-repair','pa-nht','va-location-finder','pa-link'];")
    html = replace_line(html, 'const seniorTopics=', "const seniorTopics={daily:['pa-link','pa-aging-directory','pa-options','pa-caregiver-support','pa-chc','pa-nht'],accessibility:['pa-options','pa-chc','pa-hcbs','pa-techowl-reuse','pa-techowl-library','pa-patf','pa-phfa-access','usda-pa-home-repair'],vision:['pa-bbvs','pa-techowl-library'],hearing:['pa-odhh','pa-techowl-library'],memory:['alz-dementia-support','pa-caregiver-support','pa-options'],costs:['pa-medi','pa-chc','pa-options','pa-patf'],rights:['pa-disability-rights','pa-ombudsman','pa-link']};")
    html = replace_line(html, 'routes.seniors=', "routes.seniors=[...new Set(Object.values(seniorTopics).flat()),'cms-care-compare'];")
    # Directory caveats include known vacancies without publishing named staff.
    html = html.replace('<p class="meta">${c.contact_status', '${c.note?\'<p class="notice">\'+esc(c.note)+\'</p>\':\'\'}<p class="meta">${c.contact_status')
    html = replace_line(html, 'function renderCounty()', COUNTY_JS)
    html = replace_line(html, 'function renderSeniorGuide()', SENIOR_JS)
    html = replace_line(html, 'function renderAccessibility()', ACCESS_JS)
    html = replace_line(html, 'function audience(', "function audience(x){if(/survivors|r02-dic/.test(x.program_id))return 'Surviving spouses and other qualifying survivors';if(/aid-attendance/.test(x.program_id))return 'Qualifying veterans and survivors who need daily help';if(x.program_id==='pa-options')return 'Pennsylvania residents age 60+ with assessed unmet needs';if(/ombudsman/.test(x.program_id))return 'People receiving long-term-care services';if(/nara/.test(x.program_id))return 'Veterans and eligible records requesters';return null}")
    for name,value in [('DATA',resources),('COUNTIES',counties)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value,ensure_ascii=True).replace('<','\\u003c')+';')
    return html

COUNTY_JS = """function renderCounty(){$('print-handoff-status').textContent='';const c=COUNTIES.find(c=>c.county===$('county').value);$('print-county').textContent=c?c.county+' County, Pennsylvania':'Pennsylvania statewide resources';if(!c){$('county-panel').innerHTML='<p class="meta">Choose a county for its veterans office, statewide aging/disability and ombudsman referral routes, and a printable handoff.</p>';return}const link=DATA.find(x=>x.program_id==='pa-link'),omb=DATA.find(x=>x.program_id==='pa-ombudsman');$('county-panel').innerHTML='<div class="contact-grid">'+officeCard(c)+'<article><h2>More help for '+esc(c.county)+' County</h2><h3>Aging and disability referral</h3><p><strong>PA Link statewide routing</strong><br>'+phoneLink(link.public_contact.phone)+'</p><p>Give your county and ask for the appropriate local contact.</p><p><a href="'+esc(DATA.find(x=>x.program_id==='pa-aging-directory').official_url)+'" target="_blank" rel="noopener">Find your local aging agency</a></p><h3>Care concerns and resident rights</h3><p><strong>PA statewide ombudsman routing</strong><br>'+phoneLink(omb.public_contact.phone)+'</p><p>Ask for the local ombudsman. For immediate danger, call 911.</p><p class="meta">Statewide routing is provided here; individual local agency contacts are not yet mapped. Sources and review dates appear in the resource cards.</p></article></div>'}"""

SENIOR_JS = """function renderSeniorGuide(){const active=route==='seniors';$('seniors-guide').hidden=!active;$('community-guide').hidden=route!=='community';$('county-panel').hidden=['accessibility','seniors','community'].includes(route);if(active){$('county-title').textContent='Choose your Pennsylvania county';$('county-intro').textContent='Use PA Link or the official aging agency directory to reach local support. Military service is not required.'}if(route==='community'){$('county-title').textContent='Find Pennsylvania community connections';$('county-intro').textContent='Use official post locators while county post contacts are being researched.'}if(!active)return;const county=$('county').value;$('seniors-contact').innerHTML='<h3>Start with PA Link or your local aging agency</h3><p><strong>PA Link statewide routing</strong><br>'+phoneLink('800-753-8827')+'</p><p>Describe what is difficult and '+(county?'say you need help in '+esc(county)+' County.':'give your Pennsylvania county.')+' Ask for local assessment and the next referral.</p><p><a href="'+esc(DATA.find(x=>x.program_id==='pa-aging-directory').official_url)+'" target="_blank" rel="noopener">Find your local aging agency</a></p>';const topic=$('senior-topic').value;const guidance={daily:'Ask the aging agency about OPTIONS, meals, transportation, personal care and caregiver support. Ask PA Link about the appropriate assessment and program.',accessibility:'Ask for assessment before choosing equipment or a contractor. Explore OPTIONS, caregiver support or CHC when applicable. Ask TechOWL about reuse or trials. PATF is financing; PHFA ACCESS is tied to a qualifying home purchase.',vision:'Ask Pennsylvania BBVS for assessment of vision-related barriers and independent living support. TechOWL may offer device trials; eligibility and availability must be confirmed.',hearing:'Ask ODHH about communication access and local support. Ask TechOWL about assistive technology trials; a trial is not payment for clinical care or permanent equipment.',memory:'Contact the Alzheimer’s Association for dementia and caregiver support. Ask your aging agency whether OPTIONS or caregiver support fits; program requirements differ.',costs:'PA MEDI helps with Medicare questions. Ask about CHC screening, coverage and possible service costs. PATF loans require repayment; a referral does not guarantee funding.',rights:'Ask the ombudsman about long-term-care concerns. Disability Rights Pennsylvania handles disability-related rights concerns subject to intake and priorities.'};$('senior-guidance').innerHTML='<strong>'+(topic?'Your next step':'Choose a need, then make a referral')+'</strong><p>'+esc(guidance[topic]||'Choose a need below. These senior and disability routes do not require military service. Confirm program eligibility and current availability.')+'</p>'}"""

ACCESS_JS = """function renderAccessibility(){const active=route==='accessibility';$('accessibility-guide').hidden=!active;$('county-panel').hidden=active;$('county-title').textContent=active?'Choose where help is needed':'Your first local contact';$('county-intro').textContent=active?'Choose a Pennsylvania county for veterans referral help; PA Link routes aging and disability requests.':'County veterans offices can help with benefits and referrals. Ask which county should handle a resident who recently moved.';if(!active)return;const veteran=$('access-veteran').value,home=$('access-home').value,coverage=$('access-waiver').value,county=$('county').value,office=COUNTIES.find(c=>c.county===county),va=veteran==='yes',newHome=home==='new';const primary=coverage==='waiver'?'Your service coordinator':va?(newHome?'VA adapted housing team':'VA Prosthetics and your care team'):'PA Link: aging and disability routing';const action=coverage==='waiver'?'Ask for a home adaptation assessment and service-plan authorization.':va?(newHome?'Ask about SAH/SHA eligibility and a housing project review. HISA excludes new construction.':'Ask for a medical review and the HISA application process.'):'Ask which local agency can assess the access barrier and screen for Pennsylvania support.';const contact=coverage==='waiver'?'<p>Use your service coordinator’s direct number. For CHC, ask your managed care plan if you cannot reach the coordinator.</p>':va?'<p><a class="contact-action" href="https://www.va.gov/find-locations/?facilityType='+(newHome?'benefits':'health')+'" target="_blank" rel="noopener">'+(newHome?'Find a VA benefits office':'Find your VA medical facility')+'</a></p><p class="small">'+(newHome?'Ask for the adapted housing team.':'Ask for Prosthetic and Sensory Aids Service; use your treating facility if known.')+'</p>':'<p>'+phoneLink('800-753-8827')+'</p>';$('access-first').innerHTML='<article class="first-call"><span class="badge">Start here'+(county?' · '+esc(county)+' County, PA':'')+'</span><h3>'+esc(primary)+'</h3><p>'+esc(action)+'</p>'+contact+'</article><article><h3>Need help getting connected?</h3>'+(office?'<p><strong>'+esc(county)+' County veterans office</strong><br>'+phoneLink(office.phone)+'<br><span class="small">Veterans and surviving spouses: ask for referral and benefits help.</span></p>':'<p>Choose a county above for its veterans office.</p>')+'<p><strong>PA Link statewide routing</strong><br>'+phoneLink('800-753-8827')+'</p><p class="small">Ask for your local aging or disability contact. Not sure about military eligibility? Explore both referral routes.</p></article>';$('access-steps').innerHTML='<h3>Your next three steps</h3><ol><li><strong>Make the first call.</strong> '+esc(action)+' Ask who handles follow-up.</li><li><strong>Prepare the requested documents.</strong> '+(va&&!newHome&&coverage!=='waiver'?'For HISA, gather the prescription, Form 10-0103, owner permission, itemized estimate and before photograph. <a href="#hisa-checklist" id="open-hisa">Open the HISA checklist</a>.':'Ask the agency for assessment, owner consent, application and estimate requirements.')+'</li><li><strong>Confirm approval and remaining cost.</strong> Ask what must be authorized before work, which providers are accepted and how payment works. Agree on a follow-up date.</li></ol>';const box=(title,body)=>'<article><h3>'+title+'</h3>'+body+'</article>';let parts=[];if(veteran!=='no'){parts.push(box('Veteran route: VA clinical review','<p>Ask VA Prosthetics about HISA. New construction is excluded; SAH/SHA have separate qualifying disability and ownership rules.</p><p><a href="https://www.va.gov/find-locations/?facilityType=health" target="_blank" rel="noopener">Find your VA medical facility</a></p>'));if(home==='family')parts.push(box('Temporary family home: ask about TRA','<p>Ask VA whether Temporary Residence Adaptation applies; it requires SAH or SHA eligibility and temporary residence in a family member’s home.</p>'))}parts.push(box('Pennsylvania: assessment and authorized support','<p>'+(coverage==='waiver'?'Ask your service coordinator about home adaptation authorization.':'Ask PA Link or the Independent Enrollment Broker about assessment and waiver screening; a Medicaid card alone does not establish modification coverage.')+'</p><p>For age 60+, ask the local aging agency about OPTIONS. Qualifying caregivers can ask about caregiver support. Intellectual disability/autism waivers have separate requirements.</p><p>PA Link '+phoneLink('800-753-8827')+'<br>Independent Enrollment Broker '+phoneLink('877-550-4227')+'</p>'));parts.push(box('Temporary equipment, reuse and financing','<p>Ask TechOWL about current reused equipment and device trials. No ramp inventory or installation is guaranteed. PATF offers financing that requires repayment; it does not provide standalone ramp grants.</p><p>TechOWL '+phoneLink('800-204-7428')+'<br>PATF '+phoneLink('484-674-0506')+'</p>'));if(home==='facility')parts.push(box('Returning home: coordinate before discharge','<p>Ask the discharge planner and transition team to coordinate housing, assessment and installation before discharge. A transition referral is not an automatic ramp grant.</p><p>Nursing Home Transition '+phoneLink('800-833-5196')+'</p>'));if(home==='rent')parts.push(box('Rented home: arrange owner permission','<p>Discuss the proposed change and written consent with the owner. HISA requires notarized owner permission for renters; other funders have their own rules.</p>'));parts.push(box('Other routes to investigate','<p>PHFA ACCESS is a deferred loan tied to a qualifying PHFA home purchase, not a general grant for existing homeowners. USDA Section 504 serves qualifying rural homeowners; grants have age 62+ and very-low-income requirements, while loan rules differ.</p><p><a href="https://www.phfa.org/programs/accesshomemod.aspx" target="_blank" rel="noopener">PHFA ACCESS conditions</a> · <a href="https://www.rd.usda.gov/programs-services/single-family-housing-programs/single-family-housing-repair-loans-grants-31" target="_blank" rel="noopener">USDA Pennsylvania repair</a></p>'));$('access-routing').innerHTML=parts.join('');const checklistLink=$('open-hisa');if(checklistLink)checklistLink.onclick=()=>{$('hisa-checklist').open=true};}"""
